// Program 20: HashMaps and Conflict Resolution in Scala
// Student: Rohan Yadav | Reg. No: 26MML0020

import scala.collection.mutable

object Experiment20_HashMaps {
  def main(args: Array[String]): Unit = {
    // 1. Merge two HashMaps resolving conflicts by taking higher grade
    val map1 = Map("Rohan" -> 92, "Vedant" -> 88, "Ayush" -> 78,
"Priya" -> 84)
    val map2 = Map("Rohan" -> 85, "Vedant" -> 95, "Kalyan" -> 90,
"Priya" -> 89)

    def mergeResolveMax(m1: Map[String, Int], m2: Map[String, Int]):
Map[String, Int] = {
      (m1.keySet ++ m2.keySet).map { k =>
        val grade1 = m1.getOrElse(k, 0)
        val grade2 = m2.getOrElse(k, 0)
        k -> Math.max(grade1, grade2)
      }.toMap
    }

    val merged = mergeResolveMax(map1, map2)
    println("=== Student Grades HashMap Merge with Conflict Resolution
===")
    println(s"HashMap 1 (Original Grades): $map1")
    println(s"HashMap 2 (Updated / Re-eval): $map2")
    println("Merged HashMap (Higher Grade Selected):")

    merged.toSeq.sortBy(_._1).foreach { case (k, v) => println(s"  - $k
-> $v") }
  }
}

    // 2. Collision Chaining via Multimap (List of values per key)
    val multiGradeMap = mutable.Map[String, List[Int]]()

    def insertChained(name: String, grade: Int): Unit = {
      val existing = multiGradeMap.getOrElse(name, Nil)
      multiGradeMap(name) = existing :+ grade
    }

    println("\n=== Chained Collision Resolution Multimap (List
Chaining) ===")
    insertChained("Vedant", 88)
    insertChained("Vedant", 95) // Duplicate key appended to chain
    insertChained("Rohan", 92)
    insertChained("Rohan", 85)  // Duplicate key appended to chain
    insertChained("Ayush", 78)

    println("Final Chained Multimap Contents:")
    multiGradeMap.toSeq.sortBy(_._1).foreach {
      case (k, v) => println(s"  - $k : ${v.mkString("[", ", ", "]")}")
    }

// Program 21: Advanced Functional Combinators in Scala
// Student: Rohan Yadav | Reg. No: 26MML0020

object Experiment21_Combinators {
  def main(args: Array[String]): Unit = {
    val nums: List[Int] = (1 to 10).toList
    println(s"Initial Integer List: $nums")

    // 1. Filter: Extract even numbers
    val evens = nums.filter(x => x % 2 == 0)
    println(s"1. Even Numbers (filter):\n   $evens")

    // 2. Map: Multiply each element by 3
    val tripled = nums.map(x => x * 3)
    println(s"2. Elements Multiplied by 3 (map):\n   $tripled")

    // 3. FlatMap: Pair each integer with its square as tuples
    val pairedWithSquare = nums.flatMap(x => List((x, x * x)))
    println(s"3. Paired with Square as Tuples (flatMap):\n
$pairedWithSquare")
  }
}

    // 4. FoldLeft: Calculate product of all elements (Factorial of 10)
    val totalProduct = nums.foldLeft(1)((acc, elem) => acc * elem)

    println("=== FoldLeft Product Accumulator Computation ===")
    println(s"Input List: $nums")
    println("Accumulator initial value: 1")
    println("Reduction formula: foldLeft(1)((acc, x) => acc * x)")
    println(s"Final Accumulated Product (10!): $totalProduct")

